// AniList GraphQL adapter. Only public metadata (name, aliases, image, source
// title, description) comes from AniList; archetype, tags, abilities and all
// game stats are generated by the game and labelled as such in the UI.
import type { CharacterProvider, SearchPage, SearchQuery } from './provider';
import { ProviderError } from './provider';
import type { Archetype, PublicCharacter, Tag, Temperament } from '../types';
import { SCHEMA_VERSION } from '../types';
import { ARCHETYPES } from '../data/archetypes';
import { ABILITY_IDS, ABILITIES } from '../data/abilities';
import { Rng, hashString } from '../rng';
import { LEGEND_CHARACTERS } from '../data/legends';

// Characters with hand-made signature moves replace their plain AniList record.
const LEGEND_BY_ANILIST = new Map(LEGEND_CHARACTERS.map((c) => [c.anilistId, c]));

const ENDPOINT = 'https://graphql.anilist.co';
const TIMEOUT_MS = 8000;
const MAX_RETRIES = 2;

const CHAR_FIELDS = `id name { full alternative } image { large } description(asHtml: false) favourites gender
  media(perPage: 1, sort: [POPULARITY_DESC]) { nodes { id title { romaji english } } }`;

const CHAR_SEARCH = `query ($page: Int, $perPage: Int, $search: String) {
  Page(page: $page, perPage: $perPage) {
    pageInfo { hasNextPage currentPage }
    characters(search: $search, sort: [FAVOURITES_DESC]) { ${CHAR_FIELDS} }
  }
}`;

const SERIES_SEARCH = `query ($page: Int, $perPage: Int, $search: String) {
  Page(page: 1, perPage: 1) {
    media(search: $search, type: ANIME, sort: [POPULARITY_DESC]) {
      id title { romaji english } description(asHtml: false)
      characters(page: $page, perPage: $perPage, sort: [FAVOURITES_DESC]) {
        pageInfo { hasNextPage currentPage }
        nodes { ${CHAR_FIELDS} }
      }
    }
  }
}`;

const SERIES_BY_ID = `query ($id: Int) {
  Media(id: $id, type: ANIME) {
    id title { romaji english } description(asHtml: false)
    characters(page: 1, perPage: 25, sort: [FAVOURITES_DESC]) { nodes { ${CHAR_FIELDS} } }
  }
}`;

interface RawChar {
  id: number;
  name: { full: string | null; alternative: (string | null)[] | null } | null;
  image: { large: string | null } | null;
  description: string | null;
  favourites: number | null;
  gender?: string | null;
  media: { nodes: Array<{ id: number; title: { romaji: string | null; english: string | null } }> } | null;
}

const cache = new Map<string, unknown>();

async function gql<T>(query: string, variables: Record<string, unknown>, signal?: AbortSignal): Promise<T> {
  const key = query.length + ':' + JSON.stringify(variables);
  if (cache.has(key)) return cache.get(key) as T;
  let attempt = 0;
  for (;;) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
    const onAbort = () => ctrl.abort();
    signal?.addEventListener('abort', onAbort);
    try {
      const res = await fetch(ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({ query, variables }),
        signal: ctrl.signal,
      });
      if (res.status === 429 || res.status >= 500) {
        if (attempt < MAX_RETRIES) {
          const ra = Number(res.headers.get('Retry-After'));
          await new Promise((r) => setTimeout(r, (Number.isFinite(ra) && ra > 0 ? Math.min(ra, 10) : 1.5 * (attempt + 1)) * 1000));
          attempt++;
          continue;
        }
        throw new ProviderError(res.status === 429 ? 'AniList rate limit reached. Try again shortly.' : `AniList is unavailable (${res.status}).`, true);
      }
      if (!res.ok) throw new ProviderError(`AniList request failed (${res.status}).`, false);
      const json = await res.json();
      if (json.errors?.length) throw new ProviderError(`AniList error: ${json.errors[0].message}`, false);
      if (!json.data) throw new ProviderError('AniList returned no data.', true);
      cache.set(key, json.data);
      return json.data as T;
    } catch (e) {
      if (signal?.aborted) throw e;
      if (e instanceof ProviderError) throw e;
      if (attempt < MAX_RETRIES) { attempt++; continue; }
      throw new ProviderError(ctrl.signal.aborted ? 'AniList request timed out.' : 'Could not reach AniList (offline?).', true);
    } finally {
      clearTimeout(timer);
      signal?.removeEventListener('abort', onAbort);
    }
  }
}

const KEYWORDS: Array<[RegExp, Tag]> = [
  [/fire|flame|burn|blaze/i, 'FIRE'], [/ice|frost|snow|freez/i, 'ICE'], [/lightning|thunder|electric/i, 'LIGHTNING'],
  [/dragon/i, 'DRAGON'], [/demon|devil|curse/i, 'DEMON'], [/god|divine|angel/i, 'DIVINE'], [/magic|mage|witch|wizard|sorcer/i, 'MAGIC'],
  [/sword|warrior|soldier|knight|samurai|fight/i, 'WARRIOR'], [/assassin|ninja|kill/i, 'ASSASSIN'], [/shadow/i, 'SHADOW'],
  [/dark|vampire/i, 'DARK'], [/holy|priest|saint/i, 'HOLY'], [/wind|air/i, 'WIND'], [/earth|stone|rock/i, 'EARTH'],
  [/water|sea|ocean/i, 'WATER'], [/spirit|ghost|soul/i, 'SPIRIT'],
];

const ARCH_KEYWORDS: Array<[RegExp, Archetype]> = [
  [/assassin|ninja|stealth/i, 'Assassin'], [/shield|guard|protect|tough/i, 'Tank'], [/magic|mage|witch|wizard|spell/i, 'Mage'],
  [/archer|bow|gun|sniper|shoot/i, 'Ranger'], [/rage|berserk|beast|brute/i, 'Berserker'], [/strateg|genius|tactic|plan|intellig/i, 'Strategist'],
  [/heal|medic|doctor|support/i, 'Support'], [/sword|blade|duel|fenc/i, 'Duelist'], [/summon|familiar|contract/i, 'Summoner'],
];

const STYLE_BY_ARCH: Record<Archetype, [string, string, string]> = {
  Assassin: ['Hidden blades', 'Swift eliminations', 'Ambush tactics'],
  Tank: ['Heavy guard', 'Holding the line', 'Endurance fighting'],
  Mage: ['Focus catalyst', 'Ranged power', 'Spell barrages'],
  Ranger: ['Ranged weapon', 'Precision shots', 'Skirmishing'],
  Berserker: ['Heavy weapon', 'Relentless offense', 'All-out aggression'],
  Strategist: ['Battlefield insight', 'Reading opponents', 'Calculated play'],
  Support: ['Restorative arts', 'Keeping allies standing', 'Supportive play'],
  Duelist: ['Blade', 'One-on-one combat', 'Technical swordplay'],
  Summoner: ['Bound familiars', 'Summoned allies', 'Indirect combat'],
  Controller: ['Binding arts', 'Disabling foes', 'Battlefield control'],
};

const TEMPS: Temperament[] = ['aggressive', 'patient', 'analytical', 'reckless', 'defensive', 'hot-blooded', 'calculating', 'stoic', 'arrogant', 'cheerful'];

export function cleanDescription(d: string | null): string {
  if (!d) return '';
  return d.replace(/~!.*?!~/gs, '[spoiler hidden]').replace(/<[^>]+>/g, '').replace(/__|\*\*|_/g, '').replace(/\s+/g, ' ').trim().slice(0, 420);
}

/** Maps an AniList record to a game character. Throws on malformed data. */
export function mapAniListCharacter(raw: RawChar): PublicCharacter {
  if (!raw || typeof raw.id !== 'number' || !raw.name?.full) throw new Error('Malformed AniList character');
  const media = raw.media?.nodes?.[0];
  const series = media ? (media.title.english || media.title.romaji || 'Unknown') : 'Unknown series';
  const desc = cleanDescription(raw.description);
  const rng = new Rng(hashString('anilist:' + raw.id));
  const archetype = ARCH_KEYWORDS.find(([re]) => re.test(desc))?.[1] ?? rng.pick(Object.keys(ARCHETYPES) as Archetype[]);
  const tags: Tag[] = [];
  for (const [re, tag] of KEYWORDS) if (re.test(desc) && !tags.includes(tag) && tags.length < 2) tags.push(tag);
  const pool: Tag[] = ['FIRE', 'ICE', 'LIGHTNING', 'WIND', 'EARTH', 'WATER', 'SHADOW', 'HOLY', 'MAGIC', 'WARRIOR', 'SPIRIT', 'DARK'];
  while (tags.length < 2) { const t = rng.pick(pool); if (!tags.includes(t)) tags.push(t); }
  const matching = ABILITY_IDS.filter((id) => ABILITIES[id].element && tags.includes(ABILITIES[id].element!) && ABILITIES[id].kind !== 'ultimate');
  const pickFrom = matching.length >= 2 ? matching : ABILITY_IDS.filter((id) => ABILITIES[id].kind !== 'ultimate');
  const known = rng.shuffle(pickFrom).slice(0, 2);
  const [weapon, specialty, style] = STYLE_BY_ARCH[archetype];
  const h = hashString(String(raw.id));
  return {
    id: `anilist:${raw.id}`,
    schemaVersion: SCHEMA_VERSION,
    source: 'anilist',
    name: raw.name.full,
    aliases: (raw.name.alternative ?? []).filter((x): x is string => !!x).slice(0, 3),
    series,
    seriesId: media ? `anilist-media:${media.id}` : 'anilist-media:unknown',
    imageUrl: raw.image?.large ?? undefined,
    gender: raw.gender === 'Male' ? 'male' : raw.gender === 'Female' ? 'female' : raw.gender ? 'other' : undefined,
    bio: desc || 'No biography available from AniList.',
    specialty,
    fightingStyle: style,
    weapon,
    temperament: rng.pick(TEMPS),
    archetype,
    reach: ARCHETYPES[archetype].reach,
    tags,
    knownAbilities: known,
    verifiedFields: ['name', 'aliases', 'series', 'imageUrl', 'bio'],
    art: { hue: h % 360, hue2: (h >>> 9) % 360, hair: (h >>> 17) % 6, eye: (h >>> 21) % 4 },
  };
}

function mapList(raw: RawChar[]): PublicCharacter[] {
  const seen = new Set<string>();
  const out: PublicCharacter[] = [];
  for (const r of raw ?? []) {
    try {
      const c = LEGEND_BY_ANILIST.get(r?.id) ?? mapAniListCharacter(r);
      if (!seen.has(c.id)) { seen.add(c.id); out.push(c); }
    } catch { /* skip malformed records */ }
  }
  return out;
}

/** Random characters from AniList's most popular few thousand, for auto-fill. */
export async function randomPopular(count: number, signal?: AbortSignal): Promise<PublicCharacter[]> {
  const pages = new Set<number>();
  while (pages.size < Math.max(1, Math.ceil(count / 25))) pages.add(1 + Math.floor(Math.random() * 60));
  const out: PublicCharacter[] = [];
  for (const page of pages) {
    const data = await gql<{ Page: { characters: RawChar[] } }>(CHAR_SEARCH, { page, perPage: 50 }, signal);
    out.push(...mapList(data.Page?.characters ?? []));
  }
  return new Rng(hashString(String(Math.random()))).shuffle(out).slice(0, count);
}

export const aniListProvider: CharacterProvider = {
  id: 'anilist',
  label: 'All Anime (online)',
  online: true,
  async search(q: SearchQuery, signal?: AbortSignal): Promise<SearchPage> {
    const search = q.text.trim() || undefined;
    if (q.field === 'series' && search) {
      const data = await gql<{ Page: { media: Array<{ characters: { pageInfo: { hasNextPage: boolean }; nodes: RawChar[] } }> } }>(
        SERIES_SEARCH, { page: q.page, perPage: q.perPage, search }, signal);
      const m = data.Page?.media?.[0];
      if (!m) return { items: [], page: q.page, hasNext: false };
      return { items: mapList(m.characters.nodes), page: q.page, hasNext: !!m.characters.pageInfo?.hasNextPage };
    }
    const data = await gql<{ Page: { pageInfo: { hasNextPage: boolean }; characters: RawChar[] } }>(
      CHAR_SEARCH, { page: q.page, perPage: q.perPage, search }, signal);
    if (!data.Page || !Array.isArray(data.Page.characters)) throw new ProviderError('Unexpected AniList response.', true);
    let items = mapList(data.Page.characters);
    if (q.archetype) items = items.filter((c) => c.archetype === q.archetype);
    if (q.tag) items = items.filter((c) => c.tags.includes(q.tag as Tag));
    return { items, page: q.page, hasNext: !!data.Page.pageInfo?.hasNextPage };
  },
  async getSeries(seriesId: string, signal?: AbortSignal) {
    const id = Number(seriesId.replace('anilist-media:', ''));
    if (!Number.isFinite(id)) throw new ProviderError('Unknown series', false);
    const data = await gql<{ Media: { id: number; title: { romaji: string | null; english: string | null }; description: string | null; characters: { nodes: RawChar[] } } }>(
      SERIES_BY_ID, { id }, signal);
    const m = data.Media;
    return {
      series: { id: seriesId, title: m.title.english || m.title.romaji || 'Unknown', synopsis: cleanDescription(m.description), source: 'anilist' as const },
      characters: mapList(m.characters.nodes),
    };
  },
};
